def login(username, password):
    stored_hash = db.get_hash(username)
    if not stored_hash:
        # Still compute hash to prevent timing user enumeration
        ph.hash('dummy')
        return False
    pepper = get_pepper()
    combined = pepper + password
    try:
        ph.verify(stored_hash, combined)
        return True
    except:
        return False
